"""Command-line parsing for the monitor.

Options stop at the first command argument.  In particular, command options are
not consumed by this parser; they are passed on as part of the command string.
"""
import difflib
import math
import os
import re
import sys
from dataclasses import dataclass, field

HELP = '''HELP_PLACEHOLDER'''


@dataclass
class Options:
    batch: bool = False
    beep: bool = False
    border: bool = False
    with_scrollbar: bool = False
    mouse: bool = False
    color: bool = False
    reverse: bool = False
    compress: bool = False
    no_title: bool = False
    enable_summary_char: bool = False
    line_number: bool = False
    no_help_banner: bool = False
    no_summary: bool = False
    exec: bool = False
    diff_output_only: bool = False
    precise: bool = False
    aftercommand: str = ''
    logfile: object = None
    shell: str = 'sh -c'
    interval: float = 2.0
    limit: int = 5000
    tab_size: int = 4
    differences: str = 'none'
    output: str = 'output'
    keymap: list = field(default_factory=list)
    command: object = None
    program: str = 'executable'


SHORT = dict(zip('bBcrCtNxOAlsnLdoKhV', [
    'batch', 'beep', 'color', 'reverse', 'compress', 'no-title',
    'line-number', 'exec', 'diff-output-only', 'aftercommand',
    'logfile', 'shell', 'interval', 'limit', 'differences', 'output',
    'keymap', 'help', 'version']))
FLAGS = set('batch beep border with-scrollbar mouse color reverse compress no-title enable-summary-char line-number no-help-banner no-summary exec diff-output-only precise help version'.split())
VALUES = {'aftercommand': 'after_command', 'logfile': 'logfile',
          'shell': 'shell_command', 'interval': 'interval', 'limit': 'limit',
          'tab-size': 'tab_size', 'differences': 'differences', 'output': 'output',
          'keymap': 'keymap'}
OPTIONAL = {'logfile', 'differences', 'output'}
ENUMS = {'differences': ['none', 'watch', 'line', 'word'],
         'output': ['output', 'stdout', 'stderr']}


def fail(message, program='executable', usage=False, custom=False, usage_line=None):
    sys.stderr.write('error: ' + message + '\n')
    if usage or custom:
        if usage_line is None:
            usage_line = ('hwatch' if custom else program) + ' [OPTIONS] [command]...'
        sys.stderr.write('\nUsage: ' + usage_line + '\n')
    sys.stderr.write("\nFor more information, try '--help'.\n")
    raise SystemExit(2)


def panic(message, location, worker=False):
    import threading
    name = '<unnamed>' if worker else 'main'
    sys.stderr.write("\nthread '%s' (%d) panicked at %s:\n%s\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n" %
                     (name, threading.get_native_id(), location, message))
    sys.stderr.flush()
    if not worker:
        raise SystemExit(101)


def known_token(token):
    if token == '--':
        return True
    if token.startswith('--'):
        return token[2:].split('=', 1)[0] in FLAGS | VALUES.keys()
    if token.startswith('-') and len(token) > 1:
        return all(c in SHORT for c in token[1:])
    return False


def label(name):
    if name in OPTIONAL:
        return '--%s [<%s>]' % (name, VALUES[name])
    return '--%s <%s>' % (name, VALUES[name])


def parse_value(name, value):
    if name in ENUMS:
        if value not in ENUMS[name]:
            msg = "invalid value '%s' for '%s'\n  [possible values: %s]" % (value, label(name), ', '.join(ENUMS[name]))
            close = difflib.get_close_matches(value, ENUMS[name], n=1, cutoff=.8)
            if close:
                msg += "\n\n  tip: a similar value exists: '%s'" % close[0]
            fail(msg)
        return value
    if name == 'interval':
        try:
            if not re.fullmatch(r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)', value, re.I):
                raise ValueError()
            return float(value)
        except ValueError:
            detail = 'cannot parse float from empty string' if not value else 'invalid float literal'
            fail("invalid value '%s' for '%s': %s" % (value, label(name), detail))
    if name in ('limit', 'tab-size'):
        bound = 4294967295 if name == 'limit' else 65535
        error = None
        if not value:
            error = 'cannot parse integer from empty string'
        elif not re.fullmatch(r'[+-]?[0-9]+', value):
            error = 'invalid digit found in string'
        else:
            number = int(value)
            if number > 18446744073709551615:
                error = 'number too large to fit in target type'
            elif number < -9223372036854775808:
                error = 'number too small to fit in target type'
            elif number < 0 or number > bound:
                error = '%s is not in 0..=%d' % (number, bound)
        if error:
            fail("invalid value '%s' for '%s': %s" % (value, label(name), error))
        return number
    return value


def parse(argv=None):
    if argv is None:
        argv = sys.argv
    opts = Options(program=os.path.basename(argv[0]))
    args = os.environ.get('HWATCH', '').split() + list(argv[1:])
    seen = set()
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            opts.command = ' '.join(args[i + 1:]) if i + 1 < len(args) else None
            break
        if not known_token(arg):
            opts.command = ' '.join(args[i:])
            break
        if arg.startswith('--'):
            raw = arg[2:].split('=', 1)
            entries = [(raw[0], raw[1] if len(raw) == 2 else None)]
        else:
            entries = []
            for j, ch in enumerate(arg[1:]):
                name = SHORT[ch]
                if name in VALUES:
                    entries.append((name, arg[j + 2:] or None))
                    break
                entries.append((name, None))
        for name, attached in entries:
            if name in FLAGS:
                if attached is not None:
                    fail("unexpected value '%s' for '--%s' found; no more were expected" % (attached, name),
                         opts.program, usage=True,
                         usage_line=opts.program + ' --' + name + ' [command]...')
                if name == 'help':
                    sys.stdout.write(HELP.replace('Usage: executable ', 'Usage: ' + opts.program + ' '))
                    raise SystemExit(0)
                if name == 'version':
                    print('hwatch 0.3.19')
                    raise SystemExit(0)
                if name in seen:
                    fail("the argument '--%s' cannot be used multiple times" % name, opts.program, usage=True)
                seen.add(name)
                setattr(opts, name.replace('-', '_'), True)
                continue
            value = attached
            if value is None and i + 1 < len(args) and not known_token(args[i + 1]):
                i += 1
                value = args[i]
            if value is None:
                if name not in OPTIONAL:
                    fail("a value is required for '%s' but none was supplied" % label(name))
                if name == 'differences':
                    value = 'watch'
                elif name == 'output':
                    opts.output = None
                    continue
                else:
                    opts.logfile = None
                    continue
            parsed = parse_value(name, value)
            if name == 'keymap':
                opts.keymap.append(parsed)
            else:
                setattr(opts, name.replace('-', '_'), parsed)
        i += 1
    return opts
