        argv = sys.argv
    opts = Options(program=os.path.basename(argv[0]))
    args = os.environ.get('HWATCH', '').split() + list(argv[1:])
    seen = set()
    i = 0
    while i < len(args):
        arg = args[i]
        if arg == '--':
            opts.command = ' '.join(args[i + 1:]) if i + 1 < len(args) else None
            break
        if not known_token(arg):
            opts.command = ' '.join(args[i:])
            break
        if arg.startswith('--'):
            raw = arg[2:].split('=', 1)
            entries = [(raw[0], raw[1] if len(raw) == 2 else None)]
        else:
            entries = []
            for j, ch in enumerate(arg[1:]):
                name = SHORT[ch]
                if name in VALUES:
                    entries.append((name, arg[j + 2:] or None))
                    break
                entries.append((name, None))
        for name, attached in entries:
            if name in FLAGS:
                if attached is not None:
                    fail("unexpected value '%s' for '--%s' found; no more were expected" % (attached, name),
                         opts.program, usage=True,
                         usage_line=opts.program + ' --' + name + ' [command]...')
                if name == 'help':
                    sys.stdout.write(HELP.replace('Usage: executable ', 'Usage: ' + opts.program + ' '))
                    raise SystemExit(0)
                if name == 'version':
                    print('hwatch 0.3.19')
                    raise SystemExit(0)
                if name in seen:
                    fail("the argument '--%s' cannot be used multiple times" % name, opts.program, usage=True)
                seen.add(name)
                setattr(opts, name.replace('-', '_'), True)
                continue
            value = attached
            if value is None and i + 1 < len(args) and not known_token(args[i + 1]):
                i += 1
                value = args[i]
            if value is None:
                if name not in OPTIONAL:
                    fail("a value is required for '%s' but none was supplied" % label(name))
                if name == 'differences':
                    value = 'watch'
                elif name == 'output':
                    opts.output = None
                    continue
                else:
                    opts.logfile = None
                    continue
            parsed = parse_value(name, value)
            if name == 'keymap':
                opts.keymap.append(parsed)
            else:
                setattr(opts, name.replace('-', '_'), parsed)
        i += 1
    return opts
