    return ANSI.sub('', s)


def paint(s, style):
    return ESC + style + 'm' + s + RESET


def rust_lines(s):
    if not s:
        return []
    lines = s.split('\n')
    has_end = s.endswith('\n')
    if has_end:
        lines.pop()
    return [line[:-1] if line.endswith('\r') and (i < len(lines)-1 or has_end) else line
