class DiffLine:
    number: int
    tag: str
    parts: list

    @property
    def text(self):
        return ''.join(s for s, emphasis in self.parts)


def _append_span(spans, text, emphasis):
    if not text:
        return
    if spans and spans[-1][1] == emphasis:
        spans[-1] = (spans[-1][0] + text, emphasis)
    else:
        spans.append((text, emphasis))


def _fragment_lines(spans):
    lines = []
    current = []
    for text, emphasis in spans:
        pieces = re.findall(r'.*?(?:\r\n|\r|\n)|.+$', text, re.S)
        for piece in pieces:
            end = piece.endswith(('\r', '\n'))
            # The line terminator LF is not printed; a CR is preserved.
            visible = piece[:-1] if piece.endswith('\n') else piece
            current.append((visible, emphasis if visible else False))
            if end:
                lines.append(current)
                current = []
    if current:
        lines.append(current)
    return lines


def inline_parts(a, b):
    wa, wb = words(a), words(b)
    matcher = difflib.SequenceMatcher(None, wa, wb, autojunk=False)
    if matcher.ratio() < .5:
        return None
    old_spans, new_spans = [], []
    for kind, a0, a1, b0, b1 in matcher.get_opcodes():
        if kind in ('equal', 'replace', 'delete'):
            _append_span(old_spans, ''.join(wa[a0:a1]), kind != 'equal')
        if kind in ('equal', 'replace', 'insert'):
            _append_span(new_spans, ''.join(wb[b0:b1]), kind != 'equal')
