    a, b = diff_split(strip_ansi(before)), diff_split(strip_ansi(after))
    answer = []
    sm = difflib.SequenceMatcher(None, a, b, autojunk=False)
    for kind, a0, a1, b0, b1 in sm.get_opcodes():
