def batch_watch_line(old, new):
    length = max(len(old), len(new))
    old, new = old.ljust(length), new.ljust(length)
    out = []
    changed = False
    sequence = None
    for x, y in zip(old, new):
        if y == '\x1b':
            sequence = '\x1b'
            continue
