    mode = options.differences
    if mode == 'none':
        rows = after.split('\n')
        width = len(str(len(rows)))
        lines = [(number_prefix(i+1, width) if options.line_number else '') + s
                 for i, s in enumerate(rows)]
    elif mode == 'watch':
        rows = watch_lines(before, after)
        width = len(str(len(rows)))
        lines = [(number_prefix(i+1, width) if options.line_number else '') + batch_watch_line(a, b)
