    else:
        rows, count = line_diff(before, after)
        width = len(str(count))
        lines = []
        for row in rows:
            if options.diff_output_only and row.tag == ' ':
                continue
            color = GRAY if row.tag == ' ' else ADD_NUMBER if row.tag == '+' else DEL_NUMBER
            line = number_prefix(row.number, width, color) if options.line_number else ''
            if row.tag == ' ':
                line += '   ' + row.text
            else:
                fg = '32' if row.tag == '+' else '31'
                highlight = '42;37' if row.tag == '+' else '41;37'
                line += paint(row.tag + '  ', fg)
                for text, emphasis in row.parts:
                    line += paint(text, highlight if emphasis and mode == 'word' else fg)
