    a, b = diff_split(strip_ansi(before)), diff_split(strip_ansi(after))
    added = removed = 0
    for tag, a0, a1, b0, b1 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if tag != 'equal':
            added += b1-b0
            removed += a1-a0
