        return added, removed, 0, 0
    add_chars = del_chars = 0
    for tag, a0, a1, b0, b1 in difflib.SequenceMatcher(None, strip_ansi(before), strip_ansi(after), autojunk=False).get_opcodes():
        if tag != 'equal':
            add_chars += b1-b0
            del_chars += a1-a0
    return added, removed, add_chars, del_chars
