"""Execution, scheduling and persistent result records."""
import datetime
import errno
import json
import math
import os
import queue
import shlex
import subprocess
import sys
import threading
import time
from .cli import fail, panic
from .formatting import paint, GRAY, batch_format

FIELDS = ('timestamp', 'command', 'status', 'output', 'stdout', 'stderr')
EMPTY = dict(timestamp='', command='', status=True, output='', stdout='', stderr='')


def json_text(value):
    return json.dumps(value, ensure_ascii=False, separators=(',', ':'))


def result_equal(a, b):
    return all(a.get(k) == b.get(k) for k in FIELDS if k != 'timestamp')


def timestamp():
    return datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')[:-3]


class RecordError(Exception):
    def __init__(self, text, line=1, column=1):
        self.text, self.line, self.column = text, line, column


def _json_error(text, error):
    pos = error.pos
    message = error.msg
    c = text[pos:pos+1]
    if pos >= len(text):
        if 'string' in message.lower():
            message = 'EOF while parsing a string'
        elif text.rstrip().endswith(('{', ':', ',')) or text.lstrip().startswith('{'):
            message = 'EOF while parsing an object'
        else:
            message = 'EOF while parsing a value'
        return RecordError(message, error.lineno, max(0, error.colno-1))
    if message == 'Expecting value':
        if c in 'ntf':
            message = 'expected ident'
            return RecordError(message, error.lineno, error.colno+1)
        message = 'expected value'
    elif message.startswith('Expecting property'):
        message = 'key must be a string'
    elif message.startswith("Expecting ':'"):
        message = "expected `:`"
    elif message.startswith("Expecting ','"):
        message = "expected `,` or `}`"
    elif message.startswith('Invalid control'):
        message = 'control character (\\u0000-\\u001F) found while parsing a string'
    elif message.startswith('Invalid \\escape'):
        message = 'invalid escape'
    return RecordError(message, error.lineno, error.colno)


def read_records(text):
    decoder = json.JSONDecoder()
    records = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos >= len(text):
            return records
        try:
            item, end = decoder.raw_decode(text, pos)
        except json.JSONDecodeError as e:
            raise _json_error(text, e)
        line = text.count('\n', 0, end) + 1
        column = end - (text.rfind('\n', 0, end) + 1)
        if isinstance(item, list):
            if len(item) != 6:
                raise RecordError('invalid length %d, expected struct CommandResultData with 6 elements' % len(item), line, column)
            item = dict(zip(FIELDS, item))
        if not isinstance(item, dict):
            kind = 'null' if item is None else ('boolean `%s`' % str(item).lower() if isinstance(item, bool) else 'string %s' % json.dumps(item) if isinstance(item, str) else 'integer `%s`' % item)
            raise RecordError('invalid type: %s, expected struct CommandResultData' % kind, line, column)
        for k in FIELDS:
            if k not in item:
                raise RecordError('missing field `%s`' % k, line, column)
            expected = bool if k == 'status' else str
            if type(item[k]) is not expected:
                v = item[k]
                desc = 'null' if v is None else 'boolean `%s`' % str(v).lower() if isinstance(v, bool) else 'integer `%s`' % v if isinstance(v, int) else 'string %s' % json.dumps(v)
                raise RecordError('invalid type: %s, expected %s' % (desc, 'a boolean' if k == 'status' else 'a string'), line, column)
        records.append({k: item[k] for k in FIELDS})
        pos = end


def load_log(options):
    path = options.logfile
    if path is None:
        return []
    if path == '':
        panic('called `Option::unwrap()` on a `None` value', 'src/main.rs:460:41')
    parent = os.path.dirname(path) or '.'
    if not os.path.isdir(parent):
        fail('directory %s is not exists.' % json.dumps(parent, ensure_ascii=False), custom=True)
    if not os.path.exists(path):
        return []
    reason = None
    detail = ''
    try:
        if os.stat(path).st_size == 0 and not os.path.isdir(path):
            reason = 'empty'
        else:
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    return read_records(f.read())
            except UnicodeDecodeError:
                raise RecordError('invalid unicode code point')
    except RecordError as e:
        reason = 'json parse error'
        detail = 'Error(%s, line: %d, column: %d)\n' % (json.dumps(e.text, ensure_ascii=False), e.line, e.column)
    except OSError as e:
        reason = 'json parse error'
        detail = 'Error(%s, line: 0, column: 0)\n' % json.dumps('%s (os error %d)' % (e.strerror, e.errno))
    if reason:
        sys.stderr.write('file %s is exists and %s.\n%s' % (json.dumps(path, ensure_ascii=False), reason, detail))
        sys.stderr.flush()
        while True:
            sys.stdout.write('Log to the same file? (Y/n) ')
            sys.stdout.flush()
            response = sys.stdin.readline().strip().lower()
            if response in ('n', 'no'):
                raise SystemExit(1)
            if response in ('', 'y', 'yes'):
                break
    return []


def append_log(path, result):
    if path is None:
        return
    try:
        with open(path, 'a', encoding='utf-8') as f:
            f.write(json_text(result) + '\n')
    except OSError:
        pass


class CommandPanic(Exception):
    pass


def command_argv(command, options, direct=None):
    use_direct = options.exec if direct is None else direct
    raw = command if use_direct else options.shell
    try:
        words = shlex.split(raw, posix=True, comments=False)
    except ValueError:
        panic('shell command parse error.: ParseError', 'src/exec.rs:%d:%.2d' % ((337, 54) if use_direct else (342, 48)), worker=True)
        raise CommandPanic()
    if not words:
        panic('index out of bounds: the len is 0 but the index is 0',
              'src/exec.rs:203:55' if use_direct else 'src/exec.rs:345:42', worker=True)
        raise CommandPanic()
    if use_direct:
        return words
    if any('{COMMAND}' in word for word in words):
        return [word.replace('{COMMAND}', command) for word in words]
    return words + [command]


def execute(command, options):
    args = command_argv(command, options)
    result = dict(EMPTY)
    result['command'] = command
    try:
        p = subprocess.Popen(args, stdin=subprocess.DEVNULL, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        pieces = []
        streams = {}
        def read_stream(name, f):
            data = f.read().decode('utf-8', 'replace')
            streams[name] = data
            pieces.append(data)
            f.close()
        readers = [threading.Thread(target=read_stream, args=(name, f))
                   for name, f in [('stdout', p.stdout), ('stderr', p.stderr)]]
        for t in readers:
            t.start()
        status = p.wait()
        for t in readers:
            t.join()
        result['status'] = status == 0
        result['stdout'] = streams.get('stdout', '')
        result['stderr'] = streams.get('stderr', '')
        result['output'] = ''.join(pieces)
    except (OSError, ValueError) as e:
        number = e.errno if isinstance(e, OSError) else errno.EINVAL
        message = '%s (os error %d)' % (os.strerror(number), number)
        result.update(status=False, output=message, stderr=message)
    result['timestamp'] = timestamp()
    return result


def after_command(options, before, after):
    if not options.aftercommand:
        return
    env = dict(os.environ)
    env['HWATCH_DATA'] = json_text({'before_result': before, 'after_result': after})
    try:
        # Hooks are shell expressions, independently of direct-command mode.
        args = command_argv(options.aftercommand, options, direct=False)
        subprocess.Popen(args, env=env)
    except (OSError, CommandPanic, ValueError):
        pass


def duration_error(seconds):
    if seconds < 0:
        msg = 'value is negative'
    elif not math.isfinite(seconds) or seconds >= 18446744073709551616:
        msg = 'value is either too big or NaN'
    else:
        return False
    panic('cannot convert float seconds to Duration: ' + msg,
          '/rustc/ded5c06cf21d2b93bffd5d884aa6e96934ee4234/library/core/src/time.rs:966:23', worker=True)
    return True


class Runner(threading.Thread):
    """Serial command runner with an interruptible scheduling wait."""
    def __init__(self, options):
        super().__init__(daemon=True)
        self.options = options
        self.results = queue.Queue()
        self.stop_event = threading.Event()
        self.paused = False
        self.resume_event = threading.Event()

    def run(self):
        while not self.stop_event.is_set():
            if self.paused:
                self.stop_event.wait(.02)
                continue
            start = time.monotonic()
            try:
                result = execute(self.options.command, self.options)
            except CommandPanic:
                return
            self.results.put(result)
            interval = self.options.interval
            if duration_error(interval):
                return
            delay = interval
            if self.options.precise:
                delay = max(0, interval-(time.monotonic()-start))
            self.stop_event.wait(delay)


def batch(options):
    worker = Runner(options)
    worker.start()
    previous = dict(EMPTY)
    while True:
        current = worker.results.get()
        if result_equal(previous, current):
            continue
        header = paint('=====[' + current['timestamp'] + ']=========================', GRAY)
        output = batch_format(previous[options.output], current[options.output], options)
        sys.stdout.write(header + '\n' + output)
        sys.stdout.flush()
        append_log(options.logfile, previous)
        after_command(options, previous, current)
        if options.beep:
            sys.stdout.write('\a\n')
            sys.stdout.flush()
        previous = current
