    """Return pairs of old/new rows, preserving the presence of empty rows."""
    a, b = rust_lines(before), rust_lines(after)
    out = []
    for i in range(max(len(a), len(b))):
        old = (a[i] or '\u200b') if i < len(a) else ''
        new = (b[i] or '\u200b') if i < len(b) else ''
        out.append((old, new))
    return out


def batch_watch_line(old, new):
    length = max(len(old), len(new))
    old, new = old.ljust(length), new.ljust(length)
    out = []
    changed = False
