                for text, emphasis in row.parts:
                    line += paint(text, highlight if emphasis and mode == 'word' else fg)
            lines.append(line)
    if options.reverse:
        lines.reverse()
    return '\n'.join(lines) + '\n'


def summary(before, after, characters=False):
    a, b = diff_split(strip_ansi(before)), diff_split(strip_ansi(after))
    added = removed = 0
    for tag, a0, a1, b0, b1 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if tag != 'equal':
            added += b1-b0
            removed += a1-a0
    if not characters:
        return added, removed, 0, 0
    add_chars = del_chars = 0
    for tag, a0, a1, b0, b1 in difflib.SequenceMatcher(None, strip_ansi(before), strip_ansi(after), autojunk=False).get_opcodes():
        if tag != 'equal':
            add_chars += b1-b0
            del_chars += a1-a0
    return added, removed, add_chars, del_chars
