"""A small cell-based terminal UI for browsing command history.

The renderer owns the screen rather than using a terminal-specific curses
configuration.  Layout, Unicode width, input decoding, and terminal restoration
are consequently independent of the user's terminfo installation.
"""
import math
import os
import queue
import re
import select
import signal
import sys
import termios
import time
import tty
import unicodedata
from dataclasses import dataclass, replace
from .engine import Runner, EMPTY, result_equal, append_log, after_command
from .formatting import rust_lines, strip_ansi, line_diff, watch_lines, summary, ANSI
from .keyboard import decode_keys, help_entries


@dataclass(frozen=True)
class Style:
    fg: object = None
    bg: object = None
    bold: bool = False
    reverse: bool = False
    underline: bool = False
    italic: bool = False
    dim: bool = False
    strike: bool = False

    def ansi(self):
        codes = ['0']
        for enabled, code in [(self.bold, '1'), (self.dim, '2'), (self.italic, '3'),
                              (self.underline, '4'), (self.reverse, '7'), (self.strike, '9')]:
            if enabled:
                codes.append(code)
        for name, value in [('38', self.fg), ('48', self.bg)]:
            if isinstance(value, tuple):
                codes.append(name + ';2;' + ';'.join(map(str, value)))
            elif value is not None:
                codes.append(name + ';5;' + str(value))
        return '\x1b[' + ';'.join(codes) + 'm'


NORMAL = Style()
NUMBER = Style(fg=8)
GREEN = Style(fg=2)
RED = Style(fg=1)
CYAN = Style(fg=6)
WHITE = Style(fg=7)


def cell_width(ch):
    if not ch:
        return 0
    if ch == '\u200b' or unicodedata.combining(ch[0]) or unicodedata.category(ch[0]) in ('Cc', 'Cf'):
        return 0
    return 2 if unicodedata.east_asian_width(ch[0]) in ('W', 'F') else 1


def styled_chars(text, style=NORMAL):
    return [(ch, style) for ch in text]


def _sgr(style, values):
    try:
        args = [int(x or 0) for x in values.replace(':', ';').split(';')]
    except ValueError:
        return style
    i = 0
    while i < len(args):
        a = args[i]
        if a == 0: style = NORMAL
        elif a == 1: style = replace(style, bold=True)
        elif a == 2: style = replace(style, dim=True)
        elif a == 3: style = replace(style, italic=True)
        elif a == 4: style = replace(style, underline=True)
        elif a == 7: style = replace(style, reverse=True)
        elif a == 9: style = replace(style, strike=True)
        elif a == 22: style = replace(style, bold=False, dim=False)
        elif a == 23: style = replace(style, italic=False)
        elif a == 24: style = replace(style, underline=False)
        elif a == 27: style = replace(style, reverse=False)
        elif a == 29: style = replace(style, strike=False)
        elif 30 <= a <= 37: style = replace(style, fg=a-30)
        elif 40 <= a <= 47: style = replace(style, bg=a-40)
        elif 90 <= a <= 97: style = replace(style, fg=a-90+8)
        elif 100 <= a <= 107: style = replace(style, bg=a-100+8)
        elif a == 39: style = replace(style, fg=None)
        elif a == 49: style = replace(style, bg=None)
        elif a in (38, 48) and i+1 < len(args):
            value = None
            if args[i+1] == 5 and i+2 < len(args):
                value = args[i+2]
                i += 2
            elif args[i+1] == 2 and i+4 < len(args):
                value = tuple(args[i+2:i+5])
                i += 4
            if value is not None:
                style = replace(style, **{'fg' if a == 38 else 'bg': value})
        i += 1
    return style


def ansi_chars(text, enable=False, initial=NORMAL, tab_size=4):
    output = []
    style = initial
    i = 0
    while i < len(text):
        ch = text[i]
        if ch == '\x1b':
            if enable:
                m = ANSI.match(text, i)
                if m:
                    seq = m.group()
                    if seq.startswith('\x1b[') and seq.endswith('m'):
                        style = _sgr(style, seq[2:-1])
                    i = m.end()
                    continue
                i += 1
                continue
            output.extend(styled_chars('\\x1b', style))
        elif ch == '\t':
            output.extend(styled_chars(' ' * tab_size, style))
        else:
            output.append((ch, style))
        i += 1
    return output


def _control_text(chars):
    """Resolve in-line carriage returns and backspaces before wrapping."""
    result = []
    cursor = 0
    for ch, st in chars:
        if ch == '\r':
            cursor = 0
        elif ch == '\b':
            cursor = max(0, cursor-1)
        elif ord(ch[0]) < 32 or ch == '\x7f':
            continue
        else:
            if cursor < len(result):
                result[cursor] = (ch, st)
            else:
                result.append((ch, st))
            cursor += 1
    return result


def wrap_chars(chars, width, wrap=True, horizontal=0):
    if width <= 0:
        return [[]]
    chars = _control_text(chars)
    if not wrap:
        out, x = [], 0
        for ch, st in chars:
            size = cell_width(ch)
            if x >= horizontal and x+size <= horizontal+width:
                out.append((ch, st))
            x += size
        return [out]
    # Reflow at word boundaries.  A word wider than the pane is hard-wrapped.
    tokens = []
    for item in chars:
        is_space = item[0].isspace()
        if tokens and tokens[-1][0] == is_space:
            tokens[-1][1].append(item)
        else:
            tokens.append((is_space, [item]))
    rows, row, row_width = [], [], 0
    pending_space = []
    for is_space, token in tokens:
        if is_space:
            pending_space.extend(token)
            continue
        space_width = sum(cell_width(ch) for ch, st in pending_space)
        token_width = sum(cell_width(ch) for ch, st in token)
        if row and row_width+space_width+token_width > width:
            rows.append(row)
            row, row_width = [], 0
            pending_space = []
            space_width = 0
        if pending_space:
            for ch, st in pending_space:
                if row_width+cell_width(ch) > width:
                    rows.append(row)
                    row, row_width = [], 0
                row.append((ch, st))
                row_width += cell_width(ch)
            pending_space = []
        for ch, st in token:
            size = cell_width(ch)
            if row_width + size > width:
                rows.append(row)
                row, row_width = [], 0
            row.append((ch, st))
            row_width += size
    for ch, st in pending_space:
        if row_width + cell_width(ch) <= width:
            row.append((ch, st))
            row_width += cell_width(ch)
    if row or not rows:
        rows.append(row)
    return rows


class Screen:
    def __init__(self, width, height):
        self.width, self.height = width, height
        self.cells = [[(' ', NORMAL) for x in range(width)] for y in range(height)]

    def put(self, x, y, text, style=NORMAL, max_width=None):
        return self.put_chars(x, y, styled_chars(text, style), max_width)

    def put_chars(self, x, y, chars, max_width=None):
        start = x
        right = self.width if max_width is None else min(self.width, x+max_width)
        if y < 0 or y >= self.height:
            return x
        for ch, st in chars:
            size = cell_width(ch)
            if size == 0:
                if unicodedata.combining(ch[0]) and x > start and 0 < x <= self.width:
                    old, oldst = self.cells[y][x-1]
                    self.cells[y][x-1] = (old+ch, oldst)
                continue
            if x+size > right:
                break
            if x >= 0:
                self.cells[y][x] = (ch, st)
                if size == 2:
                    self.cells[y][x+1] = ('', st)
            x += size
        return x

    def fill(self, x, y, width, height, style=NORMAL):
        for row in range(max(0,y), min(self.height,y+height)):
            for col in range(max(0,x), min(self.width,x+width)):
                self.cells[row][col] = (' ', style)

    def draw(self, cursor=None):
        out = ['\x1b[?25l']
        active = None
        for y, row in enumerate(self.cells):
            out.append('\x1b[%d;1H' % (y+1))
            for ch, st in row:
                if not ch:
                    continue
                if st != active:
                    out.append(st.ansi())
                    active = st
                out.append(ch)
        out.append('\x1b[0m')
        if cursor is not None:
            x, y = cursor
            out.append('\x1b[%d;%dH\x1b[?25h' % (y+1,x+1))
        else:
            out.append('\x1b[1;1H')
        sys.stdout.write(''.join(out))
        sys.stdout.flush()


class TerminalApp:
    def __init__(self, options, records, mapping):
        self.o = options
        self.mapping = mapping
        self.runner = Runner(options)
        self.history = list(records)
        self.latest = records[-1] if records else dict(EMPTY)
        self.last_changed = records[-1] if records else dict(EMPTY)
        self.header_visible = not options.no_title
        self.history_visible = not options.no_title
        self.hidden_marker = False
        self.focus = 'history'
        self.selection = 0
        self.history_scroll = 0
        self.watch_scroll = 0
        self.horizontal_scroll = 0
        self.wrap = True
        self.summary_visible = False
        self.show_help = False
        self.help_scroll = 0
        self.exit_dialog = False
        self.filter_kind = ''
        self.filter_text = ''
        self.applied_filter = ''
        self.applied_regex = False
        self.filter_ever_used = False
        self.editing = False
        self.edit_cursor = 0
        self.keyword_focus = -1
        self.finished = False
        self.width, self.height = 80, 24
        self.watch_height = 22
        self.watch_width = 55
        self.rendered_watch = []
        self.watch_max_width = 0
        self.summary_cache = {}
        self.views = []
        self.dirty = True
        self._enforce_limit()
        self._rebuild_views()

    def _enforce_limit(self):
        if self.o.limit and len(self.history) > self.o.limit:
            self.history = self.history[-self.o.limit:]

    def _filter_matches(self, text):
        if not self.applied_filter:
            return True
        if self.applied_regex:
            try:
                return re.search(self.applied_filter, text) is not None
            except re.error:
                return True
        return self.applied_filter in text

    def _rebuild_views(self):
        previous = ''
        self.views = []
        for index, record in enumerate(self.history):
            text = record[self.o.output]
            include = self.o.output == 'output' or text != previous
            previous = text
            if include and self._filter_matches(text):
                self.views.append(index)
        self.views.reverse()
        self.selection = min(self.selection, len(self.views))

    def _selected_records(self):
        if not self.history:
            return dict(EMPTY), dict(EMPTY)
        if self.selection and self.selection <= len(self.views):
            index = self.views[self.selection-1]
        else:
            index = len(self.history)-1
        current = self.history[index]
        if self.o.output == 'output':
            prior = self.history[max(0,index-1)]
        else:
            # Locate the previous different value of the selected output stream.
            prior = current
            for old_index in range(index-1,-1,-1):
                if self.history[old_index][self.o.output] != current[self.o.output]:
                    prior = self.history[old_index]
                    break
        return prior, current

    def _line_number(self, number, width, tag=' '):
        color = (56,119,120) if tag == '+' else (118,0,0) if tag == '-' else 8
        return styled_chars(str(number).rjust(width) + ' | ', Style(fg=color))

    def _make_watch(self):
        previous, current = self._selected_records()
        before, after = previous[self.o.output], current[self.o.output]
        rows = []
        if self.o.differences == 'none':
            # Parse across line boundaries so SGR styles can persist over newlines.
            chars = ansi_chars(after, self.o.color, tab_size=self.o.tab_size)
            charlines = [[]]
            for item in chars:
                if item[0] == '\n':
                    charlines.append([])
                else:
                    charlines[-1].append(item)
            if after.endswith('\n'):
                charlines.pop()
            if not after:
                charlines = []
            width = len(str(len(charlines)))
            for i, line in enumerate(charlines):
                if line and line[-1][0] == '\r':
                    line = line[:-1]
                rows.append((self._line_number(i+1,width) if self.o.line_number else []) + line)
        elif self.o.differences == 'watch':
            old_lines, new_lines = rust_lines(before), rust_lines(after)
            count = max(len(old_lines),len(new_lines))
            width = len(str(count))
            for i in range(count):
                old = ansi_chars(old_lines[i], self.o.color, tab_size=self.o.tab_size) if i < len(old_lines) else []
                new = ansi_chars(new_lines[i], self.o.color, tab_size=self.o.tab_size) if i < len(new_lines) else []
                out = self._line_number(i+1,width) if self.o.line_number else []
                for col in range(max(len(old),len(new))):
                    oldch = old[col][0] if col < len(old) else None
                    ch, st = new[col] if col < len(new) else (' ',NORMAL)
                    different = oldch != ch or col >= len(new)
                    out.append((ch, replace(st,reverse=True) if different else st))
                rows.append(out)
        else:
            lines, count = line_diff(before, after)
            width = len(str(count))
            for line in lines:
                if self.o.diff_output_only and line.tag == ' ':
                    continue
                out = self._line_number(line.number,width,line.tag) if self.o.line_number else []
                st = GREEN if line.tag == '+' else RED if line.tag == '-' else NORMAL
                out += styled_chars(line.tag + '  ',st)
                for text, emphasis in line.parts:
                    part_style = st
                    if emphasis and self.o.differences == 'word':
                        part_style = Style(fg=7,bg=2 if line.tag == '+' else 1)
                    out += ansi_chars(text, False, initial=part_style,tab_size=self.o.tab_size)
                rows.append(out)
        if self.o.reverse:
            rows.reverse()
        self.watch_max_width = max((sum(cell_width(ch) for ch,st in r) for r in rows),default=0)
        self.horizontal_scroll = min(self.horizontal_scroll,max(0,self.watch_max_width-self.watch_width))
        display = []
        for line in rows:
            display.extend(wrap_chars(line,self.watch_width,self.wrap,self.horizontal_scroll))
        self._highlight_keywords(display)
        self.rendered_watch = display
        self.watch_scroll = min(self.watch_scroll,max(0,len(display)-self.watch_height))

    def _highlight_keywords(self, rows):
        if not self.applied_filter:
            return
        try:
            regex = re.compile(self.applied_filter if self.applied_regex else re.escape(self.applied_filter))
        except re.error:
            return
        occurrence = 0
        for line in rows:
            text = ''.join(ch for ch, st in line)
            for match in regex.finditer(text):
                for k in range(match.start(), min(match.end(),len(line))):
                    ch, old = line[k]
                    line[k] = (ch, Style(fg=0,bg=6 if occurrence==self.keyword_focus else 3))
                occurrence += 1

    def _header(self, s):
        interval = 'Paused' if self.runner.paused else '%.3f' % self.o.interval
        x = s.put(0,0,'Every ')
        x = s.put(x,0,interval.rjust(9),CYAN)
        x = s.put(x,0,':')
        pad = self.width - (41 if self.o.no_help_banner else 66)
        cmd = self.o.command.ljust(max(0,pad))
        x = s.put(x,0,cmd, GREEN if self.latest['status'] else RED)
        x = s.put(x,0,' ')
        if not self.o.no_help_banner:
            x = s.put(x,0,'Display help with h key!',Style(reverse=True))
            x = s.put(x,0,' ')
        s.put(x,0,self.latest['timestamp'],CYAN)
        left_width = max(0,self.width-59)
        if self.filter_ever_used:
            x = s.put(0,1,self.filter_kind or ' ',WHITE)
            x = s.put(x,1,self.filter_text.ljust(left_width),Style(fg=6,bold=True) if self.filter_text else WHITE)
        else:
            x = s.put(0,1,' '*left_width,WHITE)
        status = [('Number',self.o.line_number),('Color',self.o.color),('Reverse',self.o.reverse)]
        for name, active in status:
            x = s.put(x,1,'[')
            x = s.put(x,1,name,Style(fg=2,bold=True,reverse=True) if active else NORMAL)
            x = s.put(x,1,'] ')
        for name, color in [(self.o.output.title(),3),('History' if self.focus=='history' else 'Watch  ',6),
                            ((self.o.differences.title()+('(Only)' if self.o.diff_output_only and self.o.differences in ('word','line') else '')).ljust(10),5)]:
            x = s.put(x,1,'[')
            x = s.put(x,1,name,Style(fg=color,reverse=True))
            x = s.put(x,1,'] ')

    def _summary(self, index):
        record = self.history[index]
        old = self.history[index-1] if index else EMPTY
        key = (id(record), self.o.output, self.o.enable_summary_char)
        if key not in self.summary_cache:
            self.summary_cache[key] = summary(old[self.o.output],record[self.o.output],self.o.enable_summary_char)
        return self.summary_cache[key]

    def _history(self,s,x,y,height):
        line_height = 1 + (1 if self.summary_visible else 0) + (1 if self.summary_visible and self.o.enable_summary_char else 0)
        items = [None] + self.views
        item_rows = [0] + [1+(i-1)*line_height for i in range(1,len(items))]
        selected_y = item_rows[self.selection]
        selected_height = 1 if self.selection == 0 else line_height
        if selected_y < self.history_scroll:
            self.history_scroll = selected_y
        elif selected_y+selected_height > self.history_scroll+height:
            self.history_scroll = selected_y+selected_height-height
        self.history_scroll = max(0,self.history_scroll)
        for idx,item in enumerate(items):
            yy = y + item_rows[idx] - self.history_scroll
            selected = idx == self.selection
            base = Style(bg=4 if idx==0 and self.focus=='history' else 8,bold=True) if selected else NORMAL
            if selected:
                s.fill(x,yy,25,1 if idx==0 else line_height,base)
            s.put(x,yy,'>>' if selected else '  ',replace(base,fg=7) if idx==0 and selected else base,max_width=2)
            if item is None:
                st = replace(base,fg=7 if selected else 4)
                s.put(x+2,yy,'latest',st,max_width=23)
            else:
                record=self.history[item]
                st=replace(base,fg=2 if record['status'] else 1)
                if y <= yy < y+height:
                    s.put(x+2,yy,record['timestamp'],st,max_width=23)
                if self.summary_visible:
                    additions,deletions,add_char,del_char=self._summary(item)
                    values=[('Line',additions,deletions)]
                    if self.o.enable_summary_char:
                        values.append(('Char',add_char,del_char))
                    for offset,(name,add,remove) in enumerate(values,1):
                        sy=yy+offset
                        if y <= sy < y+height:
                            px=s.put(x+2,sy,name+': ',base,max_width=23)
                            px=s.put(px,sy,'+%7d' % add,replace(base,fg=2),max_width=x+25-px)
                            s.put(px,sy,' -%7d' % remove,replace(base,fg=1),max_width=x+25-px)

    def _border(self,s,watch_total,top):
        x=watch_total-1
        if self.header_visible:
            s.put(0,2,'─'*self.width,WHITE)
            if 0 <= x < self.width:
                s.put(x,2,'┬' if self.history_visible else '┐',WHITE)
        if 0 <= x < self.width:
            for y in range(top,self.height):
                s.put(x,y,'│',WHITE)
            if self.o.with_scrollbar and len(self.rendered_watch)>self.watch_height and self.watch_height>0:
                length=max(1,round(self.watch_height*self.watch_height/len(self.rendered_watch)))
                position=round((self.watch_height-length)*self.watch_scroll/max(1,len(self.rendered_watch)-self.watch_height))
                for y in range(top+position,min(self.height,top+position+length)):
                    s.put(x,y,'█',WHITE)

    def _help(self,s):
        width=max(4,int(self.width*.8))
        height=max(3,int(self.height*.7))
        x=math.ceil((self.width-width)/2)
        y=math.ceil((self.height-height)/2)
        s.fill(x,y,width,height,Style(fg=10))
        s.put(x,y,'┌ [help] '+'─'*max(0,width-10)+'┐',WHITE,max_width=width)
        s.put(x,y+height-1,'└'+'─'*(width-2)+'┘',WHITE,max_width=width)
        for yy in range(y+1,y+height-1):
            s.put(x,yy,'│',WHITE)
            s.put(x+width-1,yy,'│',WHITE)
        lines=[]
        for key,desc in help_entries(self.mapping):
            lines.append(styled_chars(' - [',Style(fg=10))+styled_chars(key,Style(fg=3))+styled_chars('] key :',Style(fg=10)))
            lines.append(styled_chars('         ',Style(fg=10))+styled_chars(desc,Style(fg=15)))
        lines += [[],[]]
        self.help_scroll=min(self.help_scroll,max(0,len(lines)-(height-2)))
        for row,line in enumerate(lines[self.help_scroll:self.help_scroll+height-2]):
            s.put_chars(x+1,y+row+1,line,max_width=width-2)

    def _exit(self,s):
        width=32
        x=max(0,(self.width-width)//2)
        y=max(0,(self.height-5)//2)
        st=Style(fg=6,bold=True)
        body=Style(bold=True)
        s.fill(x,y,width,5,body)
        s.put(x,y,'╔ [exit] '+'═'*22+'╗',st,max_width=width)
        s.put(x,y+4,'╚'+'═'*30+'╝',st,max_width=width)
        for row,text in enumerate([' Exit hwatch?',"   Press 'Y' or 'Q'  : Quit.","   Press 'N' or 'Esc': Stay."],1):
            s.put(x,y+row,'║',st)
            s.put(x+1,y+row,text.ljust(30),body,max_width=30)
            s.put(x+31,y+row,'║',st)

    def draw(self):
        try:
            size=os.get_terminal_size(sys.stdout.fileno())
            self.width,self.height=size.columns,size.lines
        except OSError:
            return
        if self.width<1 or self.height<1:
            return
        top=2 if self.header_visible else 0
        if self.o.border and self.header_visible:
            top+=1
        watch_total=self.width-(25 if self.history_visible else 0)
        watch_total=max(0,watch_total)
        self.watch_width=max(0,watch_total-(1 if self.o.border else 0))
        self.watch_height=max(0,self.height-top)
        self._make_watch()
        s=Screen(self.width,self.height)
        if self.header_visible:
            self._header(s)
        for i,line in enumerate(self.rendered_watch[self.watch_scroll:self.watch_scroll+self.watch_height]):
            s.put_chars(0,top+i,line,max_width=self.watch_width)
        if self.o.border:
            self._border(s,watch_total,top)
        if self.history_visible:
            self._history(s,watch_total,top,self.height-top)
        elif self.hidden_marker:
            s.put(self.width-2,top,'>>',Style(fg=7,bg=4,bold=True))
        if self.show_help:
            self._help(s)
        if self.exit_dialog:
            self._exit(s)
        cursor=None
        if self.editing and self.header_visible and not self.exit_dialog:
            cursor=(min(self.width-1,1+self.edit_cursor),1)
        s.draw(cursor)
        self.dirty=False

    def _set_output(self,value):
        self.o.output=value
        self.selection=0
        self.history_scroll=self.watch_scroll=self.horizontal_scroll=0
        self._rebuild_views()

    def _start_filter(self,regex):
        self.filter_ever_used=True
        self.filter_kind='*' if regex else '/'
        self.editing=True
        self.edit_cursor=len(self.filter_text)

    def _edit(self,key,text):
        if key=='enter':
            self.editing=False
            self.applied_filter=self.filter_text
            self.applied_regex=self.filter_kind=='*'
            self.selection=self.history_scroll=0
            self.keyword_focus=-1
            self._rebuild_views()
        elif key in ('esc','ctrl-c'):
            self.editing=False
            self.filter_text=self.applied_filter
            self.edit_cursor=len(self.filter_text)
            if not self.applied_filter:
                self.filter_kind=''
        elif key=='backspace':
            if self.edit_cursor:
                self.filter_text=self.filter_text[:self.edit_cursor-1]+self.filter_text[self.edit_cursor:]
                self.edit_cursor-=1
        elif key=='delete':
            self.filter_text=self.filter_text[:self.edit_cursor]+self.filter_text[self.edit_cursor+1:]
        elif key in ('left','ctrl-b'):
            self.edit_cursor=max(0,self.edit_cursor-1)
        elif key in ('right','ctrl-f'):
            self.edit_cursor=min(len(self.filter_text),self.edit_cursor+1)
        elif key in ('home','ctrl-a'):
            self.edit_cursor=0
        elif key in ('end','ctrl-e'):
            self.edit_cursor=len(self.filter_text)
        elif key=='ctrl-u':
            self.filter_text=self.filter_text[self.edit_cursor:]
            self.edit_cursor=0
        elif key=='ctrl-k':
            self.filter_text=self.filter_text[:self.edit_cursor]
        elif isinstance(text,str) and text:
            self.filter_text=self.filter_text[:self.edit_cursor]+text+self.filter_text[self.edit_cursor:]
            self.edit_cursor+=len(text)

    def _move(self,action):
        if self.show_help:
            height=max(1,int(self.height*.7)-2)
            if action=='up': self.help_scroll=max(0,self.help_scroll-1)
            elif action=='down': self.help_scroll+=1
            elif action=='page_up': self.help_scroll=max(0,self.help_scroll-height)
            elif action=='page_down': self.help_scroll+=height
            elif action=='move_top': self.help_scroll=0
            elif action=='move_end': self.help_scroll=100000000
            return
        if self.focus=='history' and self.history_visible:
            step=max(1,self.watch_height//(1+int(self.summary_visible)+int(self.summary_visible and self.o.enable_summary_char)))
            if action=='up': self.selection=max(0,self.selection-1)
            elif action=='down': self.selection=min(len(self.views),self.selection+1)
            elif action=='page_up': self.selection=max(0,self.selection-step)
            elif action=='page_down': self.selection=min(len(self.views),self.selection+step)
            elif action=='move_top': self.selection=0
            elif action=='move_end': self.selection=len(self.views)
            self.watch_scroll=self.horizontal_scroll=0
        else:
            maximum=max(0,len(self.rendered_watch)-self.watch_height)
            if action=='up': self.watch_scroll=max(0,self.watch_scroll-1)
            elif action=='down': self.watch_scroll=min(maximum,self.watch_scroll+1)
            elif action=='page_up': self.watch_scroll=max(0,self.watch_scroll-self.watch_height)
            elif action=='page_down': self.watch_scroll=min(maximum,self.watch_scroll+self.watch_height)
            elif action=='move_top': self.watch_scroll=0
            elif action=='move_end': self.watch_scroll=maximum

    def handle(self,key,text):
        self.dirty=True
        if self.exit_dialog:
            if key in ('y','shift-y','q','shift-q'):
                self.finished=True
            elif key in ('n','shift-n','esc','ctrl-c'):
                self.exit_dialog=False
            return
        if self.editing:
            self._edit(key,text)
            return
        action=self.mapping.get(key,'none')
        if action=='none':
            return
        if action in ('up','down','page_up','page_down','move_top','move_end'):
            self._move(action)
        elif action=='quit':
            self.show_help=False
            self.exit_dialog=True
        elif action=='cancel':
            if self.show_help:
                self.show_help=False
            else:
                self.exit_dialog=True
        elif action=='help':
            self.show_help=not self.show_help
        elif action=='reset':
            self.filter_text=self.applied_filter=self.filter_kind=''
            self.selection=self.history_scroll=0
            self.keyword_focus=-1
            self._rebuild_views()
        elif action=='toggle_forcus':
            if self.history_visible:
                self.focus='watch' if self.focus=='history' else 'history'
        elif action=='forcus_watch_pane': self.focus='watch'
        elif action=='forcus_history_pane':
            if self.history_visible: self.focus='history'
        elif action=='toggle_color': self.o.color=not self.o.color
        elif action=='toggle_line_number': self.o.line_number=not self.o.line_number
        elif action=='toggle_reverse':
            self.o.reverse=not self.o.reverse
            self.watch_scroll=0
        elif action=='toggle_mouse_support':
            self.o.mouse=not self.o.mouse
            self._mouse_mode()
        elif action=='toggle_view_header_pane':
            self.header_visible=not self.header_visible
            self.history_visible=self.header_visible
            self.hidden_marker=not self.header_visible and self.focus=='history'
        elif action=='toggle_view_history_pane':
            self.history_visible=not self.history_visible
            self.focus='history' if self.history_visible else 'watch'
            self.hidden_marker=False
        elif action=='toggle_border':
            self.o.border=not self.o.border
            self.o.with_scrollbar=self.o.border
        elif action=='toggle_scroll_bar': self.o.with_scrollbar=not self.o.with_scrollbar
        elif action=='toggle_diff_mode':
            modes=['none','watch','line','word']
            self.o.differences=modes[(modes.index(self.o.differences)+1)%4]
        elif action.startswith('set_diff_mode_'):
            value=action[len('set_diff_mode_'):]
            self.o.differences='none' if value=='plane' else value
        elif action=='set_diff_only': self.o.diff_output_only=not self.o.diff_output_only
        elif action=='toggle_output_mode':
            modes=['output','stdout','stderr']
            self._set_output(modes[(modes.index(self.o.output)+1)%3])
        elif action.startswith('set_output_mode_'): self._set_output(action[len('set_output_mode_'):])
        elif action=='toggle_wrap_mode':
            self.wrap=not self.wrap
            self.horizontal_scroll=0
        elif action=='toggle_history_summary':
            if not self.o.no_summary: self.summary_visible=not self.summary_visible
        elif action=='interval_plus': self.o.interval+=.5
        elif action=='interval_minus': self.o.interval=max(.001,self.o.interval-.5)
        elif action=='toggle_pause': self.runner.paused=not self.runner.paused
        elif action=='change_filter_mode': self._start_filter(False)
        elif action=='change_regex_filter_mode': self._start_filter(True)
        elif action in ('horizontal_right','horizontal_left','horizontal_home','horizontal_end'):
            if action=='horizontal_right': self.horizontal_scroll+=1
            elif action=='horizontal_left': self.horizontal_scroll=max(0,self.horizontal_scroll-1)
            elif action=='horizontal_home': self.horizontal_scroll=0
            else: self.horizontal_scroll=max(0,self.watch_max_width-self.watch_width)
        elif action in ('next_keyword','prev_keyword'):
            self._keyword(action=='next_keyword')
        elif action in ('mouse_scroll_up','mouse_scroll_down') and self.o.mouse:
            if isinstance(text,tuple):
                self.focus='history' if self.history_visible and text[0]>=self.width-25 else 'watch'
            for _ in range(3): self._move('up' if action=='mouse_scroll_up' else 'down')
        elif action=='mouse_button_left' and self.o.mouse and isinstance(text,tuple):
            x,y=text
            if self.history_visible and x>=self.width-25:
                self.focus='history'
                top=2*int(self.header_visible)+int(self.header_visible and self.o.border)
                line=y-top+self.history_scroll
                height=1+int(self.summary_visible)+int(self.summary_visible and self.o.enable_summary_char)
                self.selection=min(len(self.views),max(0,1+(line-1)//height if line else 0))
            else: self.focus='watch'

    def _keyword(self,forward):
        if not self.applied_filter:
            return
        try:
            reg=re.compile(self.applied_filter if self.applied_regex else re.escape(self.applied_filter))
        except re.error:
            return
        matches=[]
        for i,line in enumerate(self.rendered_watch):
            matches.extend(i for _ in reg.finditer(''.join(c for c,st in line)))
        if matches:
            self.keyword_focus=(self.keyword_focus+(1 if forward else -1))%len(matches)
            row=matches[self.keyword_focus]
            if row<self.watch_scroll or row>=self.watch_scroll+self.watch_height:
                self.watch_scroll=row

    def _mouse_mode(self):
        sys.stdout.write('\x1b[?1000h\x1b[?1002h\x1b[?1006h' if self.o.mouse else '\x1b[?1000l\x1b[?1002l\x1b[?1006l')
        sys.stdout.flush()

    def _receive(self,current):
        self.latest=current
        self.dirty=True
        if result_equal(self.last_changed,current):
            return
        before=self.last_changed
        if self.selection:
            self.selection+=1
        self.history.append(current)
        self._enforce_limit()
        self.last_changed=current
        self._rebuild_views()
        append_log(self.o.logfile,current)
        after_command(self.o,before,current)
        if self.o.beep:
            sys.stdout.write('\a')
            sys.stdout.flush()

    def run(self):
        fd=sys.stdin.fileno()
        try:
            old=termios.tcgetattr(fd)
        except termios.error:
            return
        old_winch=signal.getsignal(signal.SIGWINCH)
        def resize(signum,frame):
            self.dirty=True
        signal.signal(signal.SIGWINCH,resize)
        tty.setraw(fd)
        sys.stdout.write('\x1b[?1049h\x1b[2J\x1b[?25l')
        self._mouse_mode()
        self.runner.start()
        pending=b''
        pending_since=time.monotonic()
        try:
            while not self.finished:
                while True:
                    try: self._receive(self.runner.results.get_nowait())
                    except queue.Empty: break
                if self.dirty: self.draw()
                readable,_,_=select.select([fd],[],[],.03)
                if readable:
                    data=os.read(fd,4096)
                    if not data: break
                    pending+=data
                    pending_since=time.monotonic()
                    events,pending=decode_keys(pending)
                elif pending and time.monotonic()-pending_since>.025:
                    events,pending=decode_keys(pending,final=True)
                else:
                    events=[]
                for key,text in events:
                    self.handle(key,text)
                    if self.finished: break
        finally:
            self.runner.stop_event.set()
            sys.stdout.write('\x1b[?1000l\x1b[?1002l\x1b[?1006l\x1b[0m\x1b[?25h\x1b[?1049l')
            sys.stdout.flush()
            termios.tcsetattr(fd,termios.TCSADRAIN,old)
            signal.signal(signal.SIGWINCH,old_winch)
