    def _highlight_keywords(self, rows):
        if not self.applied_filter:
            return
        try:
            regex = re.compile(self.applied_filter if self.applied_regex else re.escape(self.applied_filter))
        except re.error:
            return
        occurrence = 0
        for line in rows:
            text = ''.join(ch for ch, st in line)
            for match in regex.finditer(text):
                for k in range(match.start(), min(match.end(),len(line))):
                    ch, old = line[k]
                    line[k] = (ch, Style(fg=0,bg=6 if occurrence==self.keyword_focus else 3))
                occurrence += 1

    def _header(self, s):
        interval = 'Paused' if self.runner.paused else '%.3f' % self.o.interval
        x = s.put(0,0,'Every ')
        x = s.put(x,0,interval.rjust(9),CYAN)
        x = s.put(x,0,':')
        pad = self.width - (41 if self.o.no_help_banner else 66)
        cmd = self.o.command.ljust(max(0,pad))
        x = s.put(x,0,cmd, GREEN if self.latest['status'] else RED)
        x = s.put(x,0,' ')
        if not self.o.no_help_banner:
            x = s.put(x,0,'Display help with h key!',Style(reverse=True))
            x = s.put(x,0,' ')
        s.put(x,0,self.latest['timestamp'],CYAN)
        left_width = max(0,self.width-59)
        if self.filter_ever_used:
            x = s.put(0,1,self.filter_kind or ' ',WHITE)
            x = s.put(x,1,self.filter_text.ljust(left_width),Style(fg=6,bold=True) if self.filter_text else WHITE)
        else:
            x = s.put(0,1,' '*left_width,WHITE)
        status = [('Number',self.o.line_number),('Color',self.o.color),('Reverse',self.o.reverse)]
        for name, active in status:
            x = s.put(x,1,'[')
            x = s.put(x,1,name,Style(fg=2,bold=True,reverse=True) if active else NORMAL)
            x = s.put(x,1,'] ')
        for name, color in [(self.o.output.title(),3),('History' if self.focus=='history' else 'Watch  ',6),
                            ((self.o.differences.title()+('(Only)' if self.o.diff_output_only and self.o.differences in ('word','line') else '')).ljust(10),5)]:
            x = s.put(x,1,'[')
            x = s.put(x,1,name,Style(fg=color,reverse=True))
            x = s.put(x,1,'] ')

    def _summary(self, index):
        record = self.history[index]
        old = self.history[index-1] if index else EMPTY
        key = (id(record), self.o.output, self.o.enable_summary_char)
        if key not in self.summary_cache:
            self.summary_cache[key] = summary(old[self.o.output],record[self.o.output],self.o.enable_summary_char)
        return self.summary_cache[key]

    def _history(self,s,x,y,height):
        line_height = 1 + (1 if self.summary_visible else 0) + (1 if self.summary_visible and self.o.enable_summary_char else 0)
        items = [None] + self.views
        item_rows = [0] + [1+(i-1)*line_height for i in range(1,len(items))]
        selected_y = item_rows[self.selection]
        selected_height = 1 if self.selection == 0 else line_height
        if selected_y < self.history_scroll:
            self.history_scroll = selected_y
        elif selected_y+selected_height > self.history_scroll+height:
            self.history_scroll = selected_y+selected_height-height
        self.history_scroll = max(0,self.history_scroll)
        for idx,item in enumerate(items):
            yy = y + item_rows[idx] - self.history_scroll
            selected = idx == self.selection
            base = Style(bg=4 if idx==0 and self.focus=='history' else 8,bold=True) if selected else NORMAL
            if selected:
                s.fill(x,yy,25,1 if idx==0 else line_height,base)
            s.put(x,yy,'>>' if selected else '  ',replace(base,fg=7) if idx==0 and selected else base,max_width=2)
            if item is None:
                st = replace(base,fg=7 if selected else 4)
                s.put(x+2,yy,'latest',st,max_width=23)
            else:
                record=self.history[item]
                st=replace(base,fg=2 if record['status'] else 1)
