                            s.put(px,sy,' -%7d' % remove,replace(base,fg=1),max_width=x+25-px)

    def _border(self,s,watch_total,top):
        x=watch_total-1
        if self.header_visible:
            s.put(0,2,'─'*self.width,WHITE)
            if 0 <= x < self.width:
                s.put(x,2,'┬' if self.history_visible else '┐',WHITE)
