    def _help(self,s):
        width=max(4,int(self.width*.8))
        height=max(3,int(self.height*.7))
        x=math.ceil((self.width-width)/2)
        y=math.ceil((self.height-height)/2)
        s.fill(x,y,width,height,Style(fg=10))
        s.put(x,y,'┌ [help] '+'─'*max(0,width-10)+'┐',WHITE,max_width=width)
        s.put(x,y+height-1,'└'+'─'*(width-2)+'┘',WHITE,max_width=width)
        for yy in range(y+1,y+height-1):
            s.put(x,yy,'│',WHITE)
            s.put(x+width-1,yy,'│',WHITE)
        lines=[]
        for key,desc in help_entries(self.mapping):
            lines.append(styled_chars(' - [',Style(fg=10))+styled_chars(key,Style(fg=3))+styled_chars('] key :',Style(fg=10)))
            lines.append(styled_chars('         ',Style(fg=10))+styled_chars(desc,Style(fg=15)))
        lines += [[],[]]
        self.help_scroll=min(self.help_scroll,max(0,len(lines)-(height-2)))
        for row,line in enumerate(lines[self.help_scroll:self.help_scroll+height-2]):
            s.put_chars(x+1,y+row+1,line,max_width=width-2)

    def _exit(self,s):
        width=32
        x=max(0,(self.width-width)//2)
        y=max(0,(self.height-5)//2)
        st=Style(fg=6,bold=True)
        body=Style(bold=True)
        s.fill(x,y,width,5,body)
        s.put(x,y,'╔ [exit] '+'═'*22+'╗',st,max_width=width)
        s.put(x,y+4,'╚'+'═'*30+'╝',st,max_width=width)
        for row,text in enumerate([' Exit hwatch?',"   Press 'Y' or 'Q'  : Quit.","   Press 'N' or 'Esc': Stay."],1):
            s.put(x,y+row,'║',st)
            s.put(x+1,y+row,text.ljust(30),body,max_width=30)
            s.put(x+31,y+row,'║',st)

    def draw(self):
        try:
            size=os.get_terminal_size(sys.stdout.fileno())
            self.width,self.height=size.columns,size.lines
        except OSError:
            return
        if self.width<1 or self.height<1:
            return
        top=2 if self.header_visible else 0
        if self.o.border and self.header_visible:
            top+=1
        watch_total=self.width-(25 if self.history_visible else 0)
        watch_total=max(0,watch_total)
        self.watch_width=max(0,watch_total-(1 if self.o.border else 0))
        self.watch_height=max(0,self.height-top)
        self._make_watch()
        s=Screen(self.width,self.height)
        if self.header_visible:
            self._header(s)
        for i,line in enumerate(self.rendered_watch[self.watch_scroll:self.watch_scroll+self.watch_height]):
            s.put_chars(0,top+i,line,max_width=self.watch_width)
        if self.o.border:
            self._border(s,watch_total,top)
        if self.history_visible:
            self._history(s,watch_total,top,self.height-top)
        elif self.hidden_marker:
            s.put(self.width-2,top,'>>',Style(fg=7,bg=4,bold=True))
        if self.show_help:
            self._help(s)
        if self.exit_dialog:
            self._exit(s)
        cursor=None
        if self.editing and self.header_visible and not self.exit_dialog:
            cursor=(min(self.width-1,1+self.edit_cursor),1)
        s.draw(cursor)
        self.dirty=False

    def _set_output(self,value):
        self.o.output=value
        self.selection=0
        self.history_scroll=self.watch_scroll=self.horizontal_scroll=0
        self._rebuild_views()

    def _start_filter(self,regex):
        self.filter_ever_used=True
        self.filter_kind='*' if regex else '/'
        self.editing=True
        self.edit_cursor=len(self.filter_text)

    def _edit(self,key,text):
        if key=='enter':
            self.editing=False
            self.applied_filter=self.filter_text
            self.applied_regex=self.filter_kind=='*'
            self.selection=self.history_scroll=0
            self.keyword_focus=-1
            self._rebuild_views()
        elif key in ('esc','ctrl-c'):
            self.editing=False
            self.filter_text=self.applied_filter
            self.edit_cursor=len(self.filter_text)
            if not self.applied_filter:
                self.filter_kind=''
        elif key=='backspace':
            if self.edit_cursor:
                self.filter_text=self.filter_text[:self.edit_cursor-1]+self.filter_text[self.edit_cursor:]
                self.edit_cursor-=1
        elif key=='delete':
            self.filter_text=self.filter_text[:self.edit_cursor]+self.filter_text[self.edit_cursor+1:]
        elif key in ('left','ctrl-b'):
            self.edit_cursor=max(0,self.edit_cursor-1)
        elif key in ('right','ctrl-f'):
            self.edit_cursor=min(len(self.filter_text),self.edit_cursor+1)
        elif key in ('home','ctrl-a'):
            self.edit_cursor=0
        elif key in ('end','ctrl-e'):
            self.edit_cursor=len(self.filter_text)
        elif key=='ctrl-u':
            self.filter_text=self.filter_text[self.edit_cursor:]
            self.edit_cursor=0
        elif key=='ctrl-k':
            self.filter_text=self.filter_text[:self.edit_cursor]
        elif isinstance(text,str) and text:
            self.filter_text=self.filter_text[:self.edit_cursor]+text+self.filter_text[self.edit_cursor:]
            self.edit_cursor+=len(text)

    def _move(self,action):
        if self.show_help:
            height=max(1,int(self.height*.7)-2)
            if action=='up': self.help_scroll=max(0,self.help_scroll-1)
            elif action=='down': self.help_scroll+=1
            elif action=='page_up': self.help_scroll=max(0,self.help_scroll-height)
            elif action=='page_down': self.help_scroll+=height
            elif action=='move_top': self.help_scroll=0
            elif action=='move_end': self.help_scroll=100000000
            return
        if self.focus=='history' and self.history_visible:
            step=max(1,self.watch_height//(1+int(self.summary_visible)+int(self.summary_visible and self.o.enable_summary_char)))
            if action=='up': self.selection=max(0,self.selection-1)
            elif action=='down': self.selection=min(len(self.views),self.selection+1)
            elif action=='page_up': self.selection=max(0,self.selection-step)
            elif action=='page_down': self.selection=min(len(self.views),self.selection+step)
            elif action=='move_top': self.selection=0
            elif action=='move_end': self.selection=len(self.views)
            self.watch_scroll=self.horizontal_scroll=0
        else:
            maximum=max(0,len(self.rendered_watch)-self.watch_height)
            if action=='up': self.watch_scroll=max(0,self.watch_scroll-1)
            elif action=='down': self.watch_scroll=min(maximum,self.watch_scroll+1)
            elif action=='page_up': self.watch_scroll=max(0,self.watch_scroll-self.watch_height)
            elif action=='page_down': self.watch_scroll=min(maximum,self.watch_scroll+self.watch_height)
            elif action=='move_top': self.watch_scroll=0
            elif action=='move_end': self.watch_scroll=maximum

    def handle(self,key,text):
        self.dirty=True
        if self.exit_dialog:
            if key in ('y','shift-y','q','shift-q'):
                self.finished=True
            elif key in ('n','shift-n','esc','ctrl-c'):
                self.exit_dialog=False
            return
        if self.editing:
            self._edit(key,text)
            return
        action=self.mapping.get(key,'none')
        if action=='none':
            return
        if action in ('up','down','page_up','page_down','move_top','move_end'):
            self._move(action)
        elif action=='quit':
            self.show_help=False
            self.exit_dialog=True
        elif action=='cancel':
            if self.show_help:
                self.show_help=False
            else:
                self.exit_dialog=True
        elif action=='help':
            self.show_help=not self.show_help
        elif action=='reset':
            self.filter_text=self.applied_filter=self.filter_kind=''
            self.selection=self.history_scroll=0
            self.keyword_focus=-1
            self._rebuild_views()
        elif action=='toggle_forcus':
            if self.history_visible:
                self.focus='watch' if self.focus=='history' else 'history'
        elif action=='forcus_watch_pane': self.focus='watch'
        elif action=='forcus_history_pane':
            if self.history_visible: self.focus='history'
        elif action=='toggle_color': self.o.color=not self.o.color
        elif action=='toggle_line_number': self.o.line_number=not self.o.line_number
        elif action=='toggle_reverse':
            self.o.reverse=not self.o.reverse
            self.watch_scroll=0
        elif action=='toggle_mouse_support':
            self.o.mouse=not self.o.mouse
            self._mouse_mode()
        elif action=='toggle_view_header_pane':
            self.header_visible=not self.header_visible
            self.history_visible=self.header_visible
            self.hidden_marker=not self.header_visible and self.focus=='history'
        elif action=='toggle_view_history_pane':
            self.history_visible=not self.history_visible
            self.focus='history' if self.history_visible else 'watch'
            self.hidden_marker=False
        elif action=='toggle_border':
            self.o.border=not self.o.border
            self.o.with_scrollbar=self.o.border
        elif action=='toggle_scroll_bar': self.o.with_scrollbar=not self.o.with_scrollbar
        elif action=='toggle_diff_mode':
            modes=['none','watch','line','word']
            self.o.differences=modes[(modes.index(self.o.differences)+1)%4]
        elif action.startswith('set_diff_mode_'):
            value=action[len('set_diff_mode_'):]
            self.o.differences='none' if value=='plane' else value
        elif action=='set_diff_only': self.o.diff_output_only=not self.o.diff_output_only
        elif action=='toggle_output_mode':
            modes=['output','stdout','stderr']
            self._set_output(modes[(modes.index(self.o.output)+1)%3])
        elif action.startswith('set_output_mode_'): self._set_output(action[len('set_output_mode_'):])
        elif action=='toggle_wrap_mode':
            self.wrap=not self.wrap
            self.horizontal_scroll=0
        elif action=='toggle_history_summary':
            if not self.o.no_summary: self.summary_visible=not self.summary_visible
        elif action=='interval_plus': self.o.interval+=.5
        elif action=='interval_minus': self.o.interval=max(.001,self.o.interval-.5)
        elif action=='toggle_pause': self.runner.paused=not self.runner.paused
        elif action=='change_filter_mode': self._start_filter(False)
        elif action=='change_regex_filter_mode': self._start_filter(True)
        elif action in ('horizontal_right','horizontal_left','horizontal_home','horizontal_end'):
            if action=='horizontal_right': self.horizontal_scroll+=1
